    paddle2 = sandbox.add_beam(5.5, 2.0, 1.0, 0.5, density=25.0)
    sandbox.add_joint(hull, paddle1, (paddle1.position.x, paddle1.position.y), type='rigid')
    sandbox.add_joint(hull, paddle2, (paddle2.position.x, paddle2.position.y), type='rigid')

    return hull  # Primary control body


def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x()
    target_x = 26.0
    if front_x >= target_x:
        return  # Mission complete

    base_thrust = 520.0
    cooldown = 200
    in_water = front_x >= 10.0

    wheels = []
    paddles = []
    hull = agent_body  # Assume agent_body is the hull
    for body in sandbox.bodies:
        if body == agent_body:
            continue
        if body.position.y < 1.0:  # Land wheels
            wheels.append(body)
        elif body.position.y >= 1.8:  # Water paddles at y=2.0m
            paddles.append(body)

    # Identify left and right paddles
    left_paddle = None
    right_paddle = None
    for paddle in paddles:
        if paddle.position.x < 5.0:  # Left paddle
            left_paddle = paddle
        else:  # Right paddle
            right_paddle = paddle

    obstacles = [14.0, 17.0, 20.0]
    obstacle_proximity = 1.5  # meters for obstacle detection

    if not in_water:
        # Land propulsion using wheels
        for wheel in wheels:
            if not hasattr(wheel, 'last_thrust_step'):
                wheel.last_thrust_step = -1000
            if step_count - wheel.last_thrust_step >= cooldown:
                sandbox.apply_force(wheel, base_thrust * 0.8, 0, step_count=step_count)
                wheel.last_thrust_step = step_count
    else:
        # Water propulsion using paddles with differential thrust for steering
        for paddle in paddles:
            if not hasattr(paddle, 'last_thrust_step'):
                paddle.last_thrust_step = -1000
            if step_count - paddle.last_thrust_step >= cooldown:
                sandbox.apply_force(paddle, -base_thrust * 0.9, 0, step_count=step_count)
                paddle.last_thrust_step = step_count

        # Obstacle avoidance with vertical clearance check
        for obs_x in obstacles:
            if abs(front_x - obs_x) < obstacle_proximity:
                # Apply differential thrust to steer around the obstacle
                if left_paddle and right_paddle:
                    if not hasattr(left_paddle, 'last_thrust_step'):
                        left_paddle.last_thrust_step = -1000
                    if not hasattr(right_paddle, 'last_thrust_step'):
                        right_paddle.last_thrust_step = -1000
                    if step_count - left_paddle.last_thrust_step >= cooldown:
                        sandbox.apply_force(left_paddle, -base_thrust * 1.1, 0, step_count=step_count)
                        left_paddle.last_thrust_step = step_count
                    if step_count - right_paddle.last_thrust_step >= cooldown:
                        sandbox.apply_force(right_paddle, -base_thrust * 0.7, 0, step_count=step_count)
                        right_paddle.last_thrust_step = step_count

        # Dynamic buoyancy compensation in deep channel (16.5–19.5m)
        if 16.5 <= front_x <= 19.5:
            # Increase paddling frequency to compensate for reduced buoyancy
            if not hasattr(hull, 'last_compensation_step') or step_count - hull.last_compensation_step >= 100:
                # Apply additional force to all paddles
                if left_paddle and right_paddle:
                    if step_count - left_paddle.last_thrust_step >= cooldown:
                        sandbox.apply_force(left_paddle, -base_thrust * 1.2, 0, step_count=step_count)
                        left_paddle.last_thrust_step = step_count
                    if step_count - right_paddle.last_thrust_step >= cooldown:
                        sandbox.apply_force(right_paddle, -base_thrust * 1.2, 0, step_count=step_count)
                        right_paddle.last_thrust_step = step_count
                if not hasattr(hull, 'last_compensation_step'):
                    hull.last_compensation_step = -1000
                hull.last_compensation_step = step_count

    # Speed regulation to avoid simulation instability
    for body in wheels + paddles:
        if body.linearVelocity.x > 3.5:
            sandbox.apply_force(body, -base_thrust * 0.3, 0, step_count=step_count)

